<?php

namespace LaraGram\Ai\Telegram;

class Upload
{
    /**
     * Create a new upload instance.
     *
     * An upload is a file generated by a model, sent to Telegram as a new file.
     */
    public function __construct(
        public string $contents,
        public string $filename,
        public ?string $mimeType = null,
    ) {}

    /**
     * Write the upload to a temporary file and get its path.
     */
    public function toTemporaryFile(): string
    {
        $path = rtrim(sys_get_temp_dir(), DIRECTORY_SEPARATOR).DIRECTORY_SEPARATOR
            .'laragram-ai-'.bin2hex(random_bytes(8)).'-'.basename($this->filename);

        file_put_contents($path, $this->contents);

        register_shutdown_function(fn () => @unlink($path));

        return $path;
    }
}
